<template>
  <section class="manager"><header><div><h3>Workshop job cards</h3><p>Capture customer authorization, diagnose work, control job status and price parts separately from labor.</p></div><button class="primary" @click="open = !open">{{ open ? 'Close form' : '+ Open job card' }}</button></header>
    <form v-if="open" class="form" @submit.prevent="submit"><label>Customer<input v-model.trim="form.customer" required /></label><label>Phone<input v-model.trim="form.phone" /></label><label>Registration<input v-model.trim="form.registration" required placeholder="KDA 123A" /></label><label>Make / model<input v-model.trim="form.vehicle" required placeholder="Toyota Corolla" /></label><label>Odometer (km)<input v-model.number="form.odometer" min="0" type="number" /></label><label>Reported concern<input v-model.trim="form.issue" required /></label><label>Technician<input v-model.trim="form.technician" /></label><label>Promised date<input v-model="form.dueDate" type="date" /></label><button class="primary">Create job card</button></form>
    <div class="filters"><button v-for="filter in filters" :key="filter" :class="{active: statusFilter === filter}" @click="statusFilter = filter">{{ filter }} <b>{{ count(filter) }}</b></button><input v-model.trim="query" placeholder="Search job, plate, customer" /></div>
    <div class="table-wrap"><table><thead><tr><th>Job / date</th><th>Vehicle</th><th>Customer / tech</th><th>Reported concern</th><th>Parts (KES)</th><th>Labor (KES)</th><th>Total (KES)</th><th>Status</th></tr></thead><tbody><tr v-for="job in visible" :key="job.id"><td><strong>{{ job.number }}</strong><small>{{ job.date }}</small></td><td><strong>{{ job.registration }}</strong><small>{{ job.vehicle }} · {{ Number(job.odometer).toLocaleString() }} km</small></td><td>{{ job.customer }}<small>{{ job.technician || 'Technician unassigned' }}</small></td><td class="issue">{{ job.issue }}</td><td><input :value="job.parts" type="number" min="0" class="money" @change="$emit('update', {id:job.id,field:'parts',value:Number($event.target.value)})" /></td><td><input :value="job.labor" type="number" min="0" class="money" @change="$emit('update', {id:job.id,field:'labor',value:Number($event.target.value)})" /></td><td><strong>{{ (Number(job.parts)+Number(job.labor)).toLocaleString() }}</strong></td><td><select :value="job.status" @change="$emit('update', {id:job.id,field:'status',value:$event.target.value})"><option>Open</option><option>Diagnosing</option><option>Awaiting parts</option><option>In repair</option><option>Quality check</option><option>Ready</option><option>Collected</option></select></td></tr><tr v-if="!visible.length"><td colspan="8" class="empty">No jobs match this view. Open a job card to register a vehicle.</td></tr></tbody></table></div>
  </section>
</template>
<script setup>
import { computed, reactive, ref, watch } from 'vue'
const props = defineProps({ jobs: { type: Array, default: () => [] }, prefill: { type: Object, default: null } })
const emit = defineEmits(['create','update'])
const open = ref(false); const query = ref(''); const statusFilter = ref('All jobs')
const filters = ['All jobs','Open','In repair','Awaiting parts','Quality check','Ready','Collected']
const form = reactive({ customer:'',phone:'',registration:'',vehicle:'',odometer:0,issue:'',technician:'',dueDate:'' })
watch(() => props.prefill, (value) => { if (value) { Object.assign(form, value); open.value = true } }, { immediate: true })
const visible = computed(() => props.jobs.filter((j) => (statusFilter.value==='All jobs'||j.status===statusFilter.value) && [j.number,j.registration,j.vehicle,j.customer,j.issue].some((v)=>String(v).toLowerCase().includes(query.value.toLowerCase()))))
function count(status) { return status==='All jobs' ? props.jobs.length : props.jobs.filter(j=>j.status===status).length }
function submit() { emit('create',{...form}); Object.assign(form,{customer:'',phone:'',registration:'',vehicle:'',odometer:0,issue:'',technician:'',dueDate:''}); open.value=false }
</script>
<style scoped>
.manager{display:grid;gap:14px}header{display:flex;align-items:center;justify-content:space-between;gap:12px}h3{margin:0;font-size:18px}header p{margin:5px 0 0;color:#6c7482;font-size:12px}.primary{padding:9px 13px;border:0;border-radius:7px;background:#355fa0;color:white;font-weight:700;cursor:pointer}.form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;padding:15px;background:#f4f6f9;border-radius:9px}.form label{display:grid;gap:5px;color:#586376;font-size:11px;font-weight:700}.form input{min-width:0;padding:9px;border:1px solid #d5dbe4;border-radius:6px}.filters{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.filters button{padding:7px 9px;border:1px solid #e0e4eb;border-radius:20px;background:white;color:#647084;font-size:10px;cursor:pointer}.filters button.active{background:#eaf0fb;border-color:#b7c8e5;color:#294c83}.filters b{margin-left:4px}.filters input{margin-left:auto;min-width:190px;padding:8px;border:1px solid #d5dbe4;border-radius:6px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:11px}th,td{padding:10px 8px;border-bottom:1px solid #edf0f3;text-align:left}th{color:#758093;font-size:9px;text-transform:uppercase}td small{display:block;margin-top:4px;color:#7a8596;font-size:10px}.issue{max-width:170px;white-space:normal}.money{width:78px;padding:6px;border:1px solid #d5dbe4;border-radius:5px}.table-wrap select{max-width:125px;padding:6px;border:1px solid #d5dbe4;border-radius:5px;background:#fff}.empty{text-align:center;color:#8791a0;padding:25px}@media(max-width:750px){.form{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.form{grid-template-columns:1fr}}
</style>
